//! `AET-WO-3401` §1.3, tier 1: Sentinel-01 as ordered ("V0+",
//! `examples/sentinel-01.json`) has a board directory of its own,
//! `boards/sentinel-01-bench/`, so the reference (`sentinel-01-minimal.json`,
//! `boards/sentinel-01/`) stays P1's byte-for-byte fixture. The directory is
//! regenerated by `aethelgard-svd-hal/tests/board.rs`, as the reference's is.
//! Here: the specification validates, so its acknowledgements name exactly
//! the ledger's rows, the EXT bus's I2C2 rows included (`generate` does not
//! check them; `validate` and `verify` do).
//!
//! The committed fabrication package (`fab/sentinel-01-bench/package/`) is
//! bound here to its inputs, per pull request, in seconds (ruling Q1 (i) on
//! PR #190): this specification's and topology's hashes, the scenarios'
//! names and hashes in order, every file against `MANIFEST.json`, and
//! `emit`'s bill of materials byte for byte. The package itself is derived
//! again by `verify --against-fab` in `ci.yml`'s `bench-package` job, on
//! `main`'s push and on `workflow_dispatch`: one verify, too slow per PR.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use serde_json::{Value, json};
use sha2::{Digest, Sha256};

const SPEC: &str = "examples/sentinel-01.json";
const PACKAGE: &str = "fab/sentinel-01-bench/package";
/// The scenarios the package was verified with, in the order `MANIFEST.json`
/// records and `ci.yml`'s `bench-package` job passes them.
const SCENARIOS: [&str; 4] = [
    "scenarios/sentinel-01-bench/pullup-3k3.json",
    "scenarios/sentinel-01-bench/droop-bor3.json",
    "scenarios/sentinel-01-bench/spi-absent-u4.json",
    "scenarios/sentinel-01-bench/pullup-2k2.json",
];

fn root() -> PathBuf {
    fs::canonicalize(Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")).unwrap()
}

/// Runs the binary from the repository root with an empty `PATH`: neither
/// `validate`, `solve` nor `emit` starts a tool.
fn run(args: &[&str]) -> (Option<i32>, Value) {
    let (code, stdout) = run_raw(args);
    (code, serde_json::from_str(&stdout).unwrap())
}

/// [`run`], with stdout as printed: one line.
fn run_raw(args: &[&str]) -> (Option<i32>, String) {
    let out = Command::new(env!("CARGO_BIN_EXE_aethelgard"))
        .args(args)
        .current_dir(root())
        .stdin(Stdio::null())
        .env("PATH", "")
        .output()
        .unwrap();
    let stdout = String::from_utf8(out.stdout).unwrap();
    assert_eq!(stdout.lines().count(), 1, "{args:?}: {stdout}");
    (out.status.code(), stdout)
}

fn sha(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|b| format!("{b:02x}"))
        .collect()
}

#[test]
fn the_ordered_board_validates() {
    let (code, v) = run(&["validate", "--file", SPEC]);
    assert_eq!(code, Some(0), "{v}");
    assert_eq!(v["project_name"], "sentinel-01-bench", "{v}");
}

/// Ruling Q1 (i) on PR #190, the per-PR half: the committed package names
/// this specification, its solved topology and its scenarios by hash, holds
/// exactly the files its manifest names with those hashes, and carries the
/// bill of materials `emit` writes today, byte for byte.
#[test]
fn the_committed_package_is_bound_to_its_specification_scenarios_and_emit() {
    let pkg = root().join(PACKAGE);
    let manifest: Value =
        serde_json::from_slice(&fs::read(pkg.join("MANIFEST.json")).unwrap()).unwrap();
    assert_eq!(manifest["project"], "sentinel-01-bench");
    assert_eq!(
        manifest["specification_sha256"],
        sha(&fs::read(root().join(SPEC)).unwrap()),
        "the package was made from another specification: run verify --fab-out again"
    );
    let (code, line) = run_raw(&["solve", "--file", SPEC]);
    assert_eq!(code, Some(0), "{line}");
    assert_eq!(manifest["topology_sha256"], sha(line.trim_end().as_bytes()));

    let scenarios: Vec<Value> = SCENARIOS
        .iter()
        .map(|p| {
            let bytes = fs::read(root().join(p)).unwrap();
            let v: Value = serde_json::from_slice(&bytes).unwrap();
            json!({ "scenario": v["name"], "sha256": sha(&bytes) })
        })
        .collect();
    assert_eq!(manifest["scenarios"], Value::Array(scenarios));

    let mut on_disk = BTreeMap::new();
    for entry in fs::read_dir(&pkg).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_name().unwrap().to_str().unwrap().to_owned();
        assert!(path.is_file(), "{name} is not a regular file");
        if name != "MANIFEST.json" {
            on_disk.insert(name, Value::String(sha(&fs::read(&path).unwrap())));
        }
    }
    let named: BTreeMap<String, Value> = manifest["files"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect();
    assert_eq!(
        named, on_disk,
        "the package's files and its manifest disagree"
    );

    let out = Path::new(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("aet-3401-package-{}", std::process::id()));
    let _ = fs::remove_dir_all(&out);
    let (code, v) = run(&["emit", "--file", SPEC, "--out", out.to_str().unwrap()]);
    assert_eq!(code, Some(0), "{v}");
    assert!(
        fs::read(out.join("sentinel-01-bench.bom.csv")).unwrap()
            == fs::read(pkg.join("sentinel-01-bench.bom.csv")).unwrap(),
        "emit's bill of materials is not the package's"
    );
    fs::remove_dir_all(&out).unwrap();
}
